//! `tpt-reficon-core` — runtime support for code generated by the
//! `tpt-reficon` proc macros.
//!
//! The derive macros emit mostly standalone code, but a few shared items live
//! here so diagnostics and error handling stay uniform across generated code:
//! the [`Refine`] trait, the [`RefinementError`] runtime-check error type, and
//! the [`prelude`] re-exported by the `tpt-reficon` facade crate.

#![forbid(unsafe_code)]
#![warn(missing_docs)]

use core::fmt;

/// A refinement type: a raw value plus a mathematical predicate proven (or
/// runtime-checked) at construction.
///
/// Implemented by `#[derive(Refine)]`; user code normally relies on the
/// concrete constructors the derive generates (`new` / `try_new` /
/// `into_inner`) rather than calling into this trait directly.
pub trait Refine: Sized {
    /// The underlying raw type carried by the refined wrapper.
    type Inner;

    /// Consumes the wrapper, returning the raw inner value.
    ///
    /// There is deliberately no public constructor here that skips the check.
    /// Every value enters through the derive's `new` / `try_new`, which
    /// enforce the predicate, so a value that violates it cannot be built
    /// from safe code.
    fn into_inner(self) -> Self::Inner;
}

/// Why a runtime refinement check failed.
///
/// Carries no borrowed data so it is usable in `no_std`-ish contexts and never
/// requires the offending inner type to implement `Debug`.
///
/// Messages are `'static`: generated messages embed the refinement predicate
/// and type name, all of which are known at compile time, so the check never
/// needs to allocate.
#[derive(Clone, PartialEq, Eq)]
pub struct RefinementError {
    message: &'static str,
}

impl RefinementError {
    /// A bare refinement violation.
    pub fn new() -> RefinementError {
        RefinementError {
            message: "refinement predicate violated",
        }
    }

    /// A refinement violation with a human-readable explanation of the value
    /// and predicate involved.
    pub fn with_message(message: &'static str) -> RefinementError {
        RefinementError { message }
    }

    /// The human-readable explanation (not guaranteed stable across releases).
    pub fn message(&self) -> &str {
        self.message
    }
}

impl Default for RefinementError {
    fn default() -> Self {
        RefinementError::new()
    }
}

impl fmt::Display for RefinementError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.message)
    }
}

impl fmt::Debug for RefinementError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "RefinementError({})", self.message)
    }
}

impl std::error::Error for RefinementError {}

/// Fractional-permission accessor prototype (Phase 5). Experimental.
#[cfg(feature = "unstable")]
pub mod fractional;

/// Items re-exported as `tpt_reficon::prelude::*`.
pub mod prelude {
    pub use crate::{Refine, RefinementError};
}

#[cfg(test)]
mod tests {
    use super::*;

    struct Bounded(u8);
    impl Refine for Bounded {
        type Inner = u8;
        fn into_inner(self) -> u8 {
            self.0
        }
    }

    #[test]
    fn into_inner_returns_the_wrapped_value() {
        assert_eq!(Bounded(42).into_inner(), 42);
    }

    #[test]
    fn error_message_round_trip() {
        let plain = RefinementError::new();
        assert_eq!(plain.to_string(), "refinement predicate violated");
        assert_eq!(plain.message(), "refinement predicate violated");

        let detailed = RefinementError::with_message("`value > 0 && value <= 100` violated");
        assert_eq!(detailed.message(), "`value > 0 && value <= 100` violated");
        assert!(detailed.to_string().contains("violated"));
    }

    #[test]
    fn error_is_send_sync_clone_eq() {
        fn assert_send_sync<T: Send + Sync>() {}
        assert_send_sync::<RefinementError>();
        let a = RefinementError::with_message("x");
        let b = RefinementError::with_message("x");
        assert_eq!(a, b);
    }
}
